    minimum: number;
    maximum: number;
    value: number;
}

function readStoredHeight(key: string) {
    const stored = applicationStorage.getItem(key);
    if (stored === null) return null;
    const height = Number.parseInt(stored, 10);
    return Number.isFinite(height) && height >= 0 ? height : null;
}


